java.util.Map<java.awt.RenderingHints.Key, Object> hints = new java.util.HashMap<>();
hints.put(java.awt.RenderingHints.KEY_RENDERING, java.awt.RenderingHints.VALUE_RENDER_QUALITY);
hints.put(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);

net.coobird.thumbnailator.resizers.ProgressiveBilinearResizer resizer = 
    new net.coobird.thumbnailator.resizers.ProgressiveBilinearResizer(hints);

int targetWidth = Math.max(1, sourceImage.getWidth() / 2);
int targetHeight = Math.max(1, sourceImage.getHeight() / 2);
java.awt.image.BufferedImage dest = new java.awt.image.BufferedImage(
    targetWidth, targetHeight, java.awt.image.BufferedImage.TYPE_INT_ARGB);

// Fill destination with a known color to verify it gets overwritten
java.awt.Graphics2D g = dest.createGraphics();
g.setColor(java.awt.Color.MAGENTA);
g.fillRect(0, 0, targetWidth, targetHeight);
g.dispose();

int originalPixel = dest.getRGB(targetWidth / 2, targetHeight / 2);

resizer.resize(sourceImage, dest);

int newPixel = dest.getRGB(targetWidth / 2, targetHeight / 2);

assert originalPixel != newPixel : "Destination image was not modified by the resizer";

System.out.println("__CHECK__ ProgressiveBilinearResizer " + targetWidth + "x" + targetHeight + " pixel:" + newPixel);

